async function finalTries() {
  // We are in a Cow pen. Let's try to find something else.
  // Try walking towards the Lumbridge graveyard (Zombies) or Chicken area
  await bot.walkTo(3220, 3220);

  const targets = ["Chicken", "Zombie", "Sheep", "Butterfly"];
  let killed = [];

  for (const target of targets) {
    const result = await bot.attack(target);
    if (result.success) {
      await sdk.waitForCondition(state => {
        const player = state.player;
        return !player || !player.combat.inCombat;
      }, 15000);
      killed.push(target);
    }
  }
  return killed;
}

return await finalTries();

